{
  "root_causes": [
    {
      "service": "geo",
      "fault_kind": "network_partition",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, attr_status_code, count(*) n, round(max(duration)/1e9,2) max_s FROM abnormal_traces WHERE span_name='geo.Geo/Nearby' GROUP BY 1,2,3,4 ORDER BY 1,2,3,4",
          "claim": "All 1074 search→geo.Geo/Nearby client calls in the incident ended in Error, with durations up to about 20 s."
        },
        {
          "kind": "trace",
          "sql": "SELECT count(*) AS geo_spans_abnormal FROM abnormal_traces WHERE service_name='geo'",
          "claim": "Geo emits zero spans during the incident, against 189 in the normal period, so no request reached geo."
        },
        {
          "kind": "metric",
          "sql": "SELECT attr_k8s_pod_name pod, metric, count(*) n, round(avg(value),3) avg_v FROM abnormal_metrics WHERE attr_k8s_pod_name LIKE 'geo%' AND metric IN ('k8s.container.restarts','k8s.container.ready','container.cpu.usage') GROUP BY 1,2 ORDER BY 2",
          "claim": "Geo's pod stayed running and ready with zero restarts and kept reporting CPU samples through the incident window."
        },
        {
          "kind": "log",
          "sql": "SELECT service_name, level, message, count(*) n FROM abnormal_logs WHERE level='ERROR' GROUP BY 1,2,3",
          "claim": "Search logs 'Failed to get nearby hotels from geo service' at ERROR level, the first error in the chain."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "geo",
      "to": "search",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, attr_status_code, count(*) n, round(avg(duration)/1e6,2) avg_ms FROM abnormal_traces WHERE service_name='search' AND span_name IN ('geo.Geo/Nearby','search.Search/Nearby') GROUP BY 1,2,3,4",
          "claim": "Search's geo client calls all fail with Error, and its own Search/Nearby server spans all fail too."
        }
      ]
    },
    {
      "from": "search",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, attr_status_code, count(*) n FROM abnormal_traces WHERE service_name='frontend' AND span_name IN ('HTTP /hotels','search.Search/Nearby') GROUP BY 1,2,3,4",
          "claim": "All 864 frontend /hotels requests that call search.Search/Nearby return Error, while other frontend routes stay Unset."
        }
      ]
    }
  ]
}
```

